import ast

# Custom validation logic for SMI (Standard Model Imaging)
# Access field data with value["FieldName"]
# Raise ValidationError for failures; recommendation-level items tagged [warning]

errors = []
for i in range(len(value["DiffusionBValues"])):
    prefix = "Entry " + str(i) + ": "

    # --- Parse array-valued fields safely ---
    try:
        bvals = as_list(value["DiffusionBValues"][i])
    except Exception:
        bvals = []
        errors.append(prefix + "DiffusionBValues could not be parsed")

    try:
        dirs_per_shell = as_list(value["DirectionsPerShell"][i])
    except Exception:
        dirs_per_shell = []

    # --- Build shell -> directions mapping (by index alignment) ---
    shells = []
    for j, b in enumerate(bvals):
        n_dirs = dirs_per_shell[j] if j < len(dirs_per_shell) else None
        shells.append((b, n_dirs))

    # --- Rule 1: NumberOfDiffusionShells >= 2 (FAIL), >= 3 preferred (WARNING) ---
    try:
        n_shells = float(value["NumberOfDiffusionShells"][i])
        if n_shells < 2:
            errors.append(prefix + "At least two b-shells must be acquired")
        elif n_shells < 3:
            errors.append(prefix + "[warning] At least three b-shells are recommended for SMI")
    except Exception:
        errors.append(prefix + "NumberOfDiffusionShells could not be read")
        n_shells = None

    # --- Rule 2: at least 1 b-value in [500, 1250] recommended (WARNING) ---
    if len([b for b in bvals if 500 <= b <= 1250]) < 1:
        errors.append(prefix + "[warning] At least one b-value between 500 and 1250 s/mm2 is recommended for SMI")

    # --- Rule 3: at least 1 b-value in [1500, 2500] recommended (WARNING) ---
    if len([b for b in bvals if 1500 <= b <= 2500]) < 1:
        errors.append(prefix + "[warning] At least one b-value between 1500 and 2500 s/mm2 is recommended for SMI")

    # --- Rule 4: if 3 shells, maximal b-value recommended > 5000 (WARNING) ---
    if n_shells is not None and n_shells >= 3 and bvals:
        if max(bvals) <= 5000:
            errors.append(prefix + "[warning] With three shells, a maximal b-value above 5000 s/mm2 is recommended for SMI")

    # --- Rule 5: b-value in [500, 1250] must have >= 15 directions (FAIL), 20 preferred (WARNING) ---
    low_shell_dirs = [n for b, n in shells if 500 <= b <= 1250 and n is not None]
    if low_shell_dirs:
        total_low = sum(low_shell_dirs)
        if total_low < 15:
            errors.append(prefix + "The b-value between 500 and 1250 must have at least 15 gradient directions for SMI")
        elif total_low < 20:
            errors.append(prefix + "[warning] The b-value between 500 and 1250 has fewer than 20 gradient directions; 20 is recommended for SMI")

    # --- Rule 6: b-value > 1500 must have >= 28 directions (FAIL), 60 preferred (WARNING) ---
    high_shell_dirs = [n for b, n in shells if b > 1500 and n is not None]
    if high_shell_dirs:
        total_high = sum(high_shell_dirs)
        if total_high < 28:
            errors.append(prefix + "The b-value above 1500 must have at least 28 gradient directions for SMI")
        elif total_high < 60:
            errors.append(prefix + "[warning] The b-value above 1500 has fewer than 60 gradient directions; 60 is recommended for SMI")

warns = [m for m in errors if "[warning]" in m]
fails = [m for m in errors if "[warning]" not in m]
if fails:
    raise ValidationError(chr(10).join("• " + m for m in fails + warns))
if warns:
    raise ValidationWarning(chr(10).join("• " + m for m in warns))
